const parseUrl = s => { const m = /^(https?):\/\/([A-Za-z0-9.\-]+)(?::(\d+))?(\/[^\s]*)?$/.exec(String(s || '')); if (!m) return null; return { protocol: m[1] + ':', hostname: m[2].toLowerCase(), host: m[2].toLowerCase() + (m[3] ? ':' + m[3] : ''), href: m[0] }; };  // n8n Code sandbox has NO URL global (verified on n8n 2.41.4)
const c = $input.first().json;
if (['rights_blocked', 'policy_blocked', 'needs_human_review'].includes(c.source_status)) throw new Error('RIGHTS: source status is ' + c.source_status);
if (c.rights.decision !== 'verified') throw new Error('RIGHTS: rights gate says ' + c.rights.decision + ' - ' + JSON.stringify(c.rights.reasons));   // rights acknowledgement is only sent after this passes
const u = parseUrl(c.normalized_url); if (!u) throw new Error('VALIDATION: bad source url');
if (u.protocol !== 'https:' || !c.allowed.includes(u.hostname)) throw new Error('VALIDATION: source host not in allowed_source_domains: ' + u.hostname);
const base = c.os_base.replace(/\/+$/, ''); if (!/^https?:\/\/[A-Za-z0-9.\-]+(:\d+)?$/.test(base)) throw new Error('VALIDATION: openshorts_base_url malformed');
return [{ json: { url: u.href, os_base: base, webhook_url: c.n8n_base.replace(/\/+$/, '') + '/webhook/ca-openshorts-done' } }];

const id = $input.first().json.job_id;
if (!id || typeof id !== 'string') throw new Error('VALIDATION: unexpected OpenShorts response (no job_id) - check OpenShorts version/API');
return [{ json: { ext: id } }];

// Normalize an error output into {job_id, category, message}. Secrets are redacted before anything is persisted.
const j = $input.first().json;
const jobId = $('Load Job').first().json.job_id;
const raw = JSON.stringify(j.error ?? j).slice(0, 700);
const m = raw.match(/\b([45]\d\d)\b/); const code = m ? +m[1] : 0;
let cat = 'UNKNOWN';
if (/VALIDATION:/.test(raw)) cat = 'VALIDATION';
else if (/RIGHTS:/.test(raw)) cat = 'RIGHTS';
else if (code === 401 || code === 403 || /unauthori|invalid_grant|token (has )?expired|permission|credentials/i.test(raw)) cat = 'AUTH';
else if (code === 429 || /quota|rate.?limit|RESOURCE_EXHAUSTED/i.test(raw)) cat = 'RATE_LIMIT';
else if (code >= 500 || /ECONN|ETIMEDOUT|ENOTFOUND|EAI_AGAIN|socket hang|timed? ?out/i.test(raw)) cat = 'TRANSIENT';
else if (code >= 400) cat = 'VALIDATION';
const msg = raw.replace(/(api[_-]?key|key|token|secret|authorization|bearer)["'=: ]+[A-Za-z0-9._\-]{8,}/gi, '$1=[redacted]');
return [{ json: { job_id: jobId, category: cat, message: msg } }];

const crypto = require('crypto');
const it = $input.first().json; const secret = $env.OPENSHORTS_WEBHOOK_SECRET;
if (!secret) return [{ json: { valid: false, why: 'no secret configured' } }];
const sig = String((it.headers || {})['x-openshorts-signature'] || '');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(JSON.stringify(it.body)).digest('hex');
const a = Buffer.from(sig), b = Buffer.from(expected);
const valid = a.length === b.length && crypto.timingSafeEqual(a, b);
const body = it.body || {};
return [{ json: { valid, event: body.event, status: body.status, job_id: body.job_id, clips: Array.isArray(body.clips) ? body.clips.slice(0, 30) : [], error: body.error ? String(body.error).slice(0, 300) : null } }];

